/**
 * Pricing is a pure calculation service over versioned rules (zones, fees, surcharges). It holds no
 * orders and publishes no events. QuoteCart is THE price calculation: cart, checkout preview and the
 * order saga all call it, so what the customer sees is what they're charged. It mirrors
 * apps/customer/src/features/cart/totals.ts exactly:
 *
 *   count         = Σ qty
 *   subtotal      = Σ unit_price × qty
 *   saving        = offer_saving set ? min(offer_saving, subtotal)
 *                                    : round(subtotal × restaurant_discount_percent / 100)
 *   plus_waives   = plus_active && subtotal ≥ plus_free_delivery_from (Rs 1,500)
 *   delivery_fee  = mode == DELIVERY && count > 0 && !plus_waives && !free_delivery_offer
 *                     ? zone delivery fee (base + per-km beyond 2 km + active surcharges) : 0
 *   small_order   = count > 0 && subtotal < zone.small_order_under (Rs 500) ? zone.small_order_fee (Rs 60) : 0
 *   promo         = min(promo_discount, subtotal − saving)       // a promo can't take food below zero
 *   tip           = mode == DELIVERY ? max(0, tip) : 0
 *   before_credit = subtotal − saving − promo + delivery_fee + small_order + tip
 *   credit        = min(max(0, credit_available), before_credit)  // never more than the bill
 *   total         = before_credit − credit
 *
 * Rounding: all amounts are minor units; percentages round half away from zero to whole rupees
 * (multiples of 100 minor units) to match the apps, which only show whole rupees.
 */
export type PricingServiceService = typeof PricingServiceService;
